         if len(candidates) == 1:
             return candidates[0], True
+        if not candidates:
+            # Enclosing namespaces (innermost first): C# makes Demo.Widget visible
+            # inside Demo.Inner without a using. Only consulted when the scopes
+            # above know nothing about the name, so no existing binding changes.
+            parts = self._namespace(source_node).split(".")
+            for i in range(len(parts) - 1, 0, -1):
+                hit = self.type_def_index.get((".".join(parts[:i]), label))
+                if hit:
+                    return hit, True
